INSERT INTO inquiries (id, full_name, email, subject, message, status, admin_response, responded_at) VALUES
                                                                                                         (1, 'Kumari Weerakkody', 'kumari.w@example.com', 'Electric Charging', 'Are Tesla Supercharger fees included in the daily rental rate?', 'responded', 'Tesla Supercharger fees are billed to the owner account and invoiced post trip.', '2024-02-01 10:30:00'),
                                                                                                         (2, 'Mahesh Senaratne', 'mahesh.s@example.com', 'Cross-Border Travel', 'Can I drive the Land Rover Defender across to remote northern forestry zones?', 'responded', 'Designated off-limit forestry zones require special platform authorization.', '2024-02-02 11:00:00'),
                                                                                                         (3, 'Tharuka Samaraweera', 'tharuka.s@example.com', 'Security Deposit', 'When is the temporary security hold released after vehicle dropoff?', 'responded', 'Security holds are automatically released within 48 hours of vehicle check in.', '2024-02-03 14:15:00'),
                                                                                                         (4, 'Sunil Jayakody', 'sunil.j@example.com', 'Chauffeur Services', 'Can I hire an assigned professional driver for an out of town trip?', 'responded', 'Yes, select hired driver arrangement during booking to assign an available driver.', '2024-02-04 09:45:00'),
                                                                                                         (5, 'Anusha Mallawarachchi', 'anusha.m@example.com', 'Pet Policy', 'Are small dogs permitted inside the vehicles if kept inside clean travel crates?', 'responded', 'Pet policies vary by vehicle host. Please check the individual vehicle listing details.', '2024-02-05 16:20:00'),
                                                                                                         (6, 'Roshantha De Mel', 'roshantha.demel@example.com', 'Airport Delivery', 'Can the host deliver the Porsche Carrera directly to terminal curbside pickup?', 'pending', NULL, NULL),
                                                                                                         (7, 'Himaya Kulathunga', 'himaya.k@example.com', 'Insurance Coverage', 'What level of collision damage waiver is standard on high performance sports cars?', 'pending', NULL, NULL),
                                                                                                         (8, 'Ajith Weerasinghe', 'ajith.w@example.com', 'Late Return Fees', 'What is the grace period before an hourly overtime fee takes effect?', 'pending', NULL, NULL),
                                                                                                         (9, 'Anoma Dharmasena', 'anoma.d@example.com', 'Cancellation Window', 'Can I cancel my confirmed reservation without penalty 48 hours in advance?', 'responded', 'Full refunds apply when cancellations are requested at least 24 hours prior to pickup.', '2024-02-09 13:00:00'),
                                                                                                         (10, 'Bandula Gunawardena', 'bandula.g@example.com', 'Manual Transmission', 'Do I need special certification before hiring manual transmission sports cars?', 'responded', 'A valid unrestricted driver license is sufficient; our team verifies manual driving competency.', '2024-02-10 17:30:00'),
                                                                                                         (11, 'Nilmini Tennakoon', 'nilmini.t@example.com', 'Corporate Accounts', 'Do you offer consolidated invoicing for corporate weekly executive bookings?', 'responded', 'Yes, our business concierge team will contact you directly to configure corporate billing.', '2024-02-11 11:15:00'),
                                                                                                         (12, 'Prabath Jayasuriya', 'prabath.j@example.com', 'Mileage Extension', 'Can I purchase an unlimited mileage bundle for an interstate road journey?', 'pending', NULL, NULL),
                                                                                                         (13, 'Malani Bulathsinghala', 'malani.b@example.com', 'Child Car Seats', 'Are sanitized infant car seats available upon vehicle delivery request?', 'pending', NULL, NULL),
                                                                                                         (14, 'Gamini Fonseka', 'gamini.f@example.com', 'Age Restrictions', 'Is there an underage driver surcharge for drivers between 21 and 24 years old?', 'responded', 'Yes, a standard young driver protection fee applies to all renters under age 25.', '2024-02-14 10:20:00'),
                                                                                                         (15, 'Damayanthi Jayakody', 'damayanthi.j@example.com', 'Host Onboarding', 'How long does host vehicle review take after registration documents are submitted?', 'responded', 'Vehicle listings are reviewed by administrators within two business days.', '2024-02-15 15:40:00'),
                                                                                                         (16, 'Upul Chandana', 'upul.c@example.com', 'Payment Methods', 'Can I pay for my luxury vehicle reservation using commercial debit cards?', 'pending', NULL, NULL),
                                                                                                         (17, 'Chandi Seneviratne', 'chandi.s@example.com', 'Navigation Systems', 'Do all vehicles come equipped with pre loaded GPS navigation systems?', 'responded', 'All platform vehicles feature integrated GPS navigation or Apple CarPlay/Android Auto.', '2024-02-17 12:00:00'),
                                                                                                         (18, 'Nishan Daluwatte', 'nishan.d@example.com', 'Toll Transponders', 'Are automatic electronic highway toll passes provided with vehicles?', 'responded', 'All vehicles include toll transponders; tolls accrued will be billed post reservation.', '2024-02-18 16:50:00'),
                                                                                                         (19, 'Sujatha Attanayake', 'sujatha.a@example.com', 'Fuel Replacement', 'Do I need to return hybrid and electric vehicles at 100 percent charge?', 'responded', 'Electric vehicles must be returned with at least 80 percent battery state of charge.', '2024-02-19 09:30:00'),
                                                                                                         (20, 'Ruwan Kodikara', 'ruwan.k@example.com', 'Dispute Resolution', 'How do I submit dashcam footage regarding an unfair post trip cleaning fee?', 'pending', NULL, NULL),
                                                                                                         (21, 'Pavithra Wanniarachchi', 'pavithra.w@example.com', 'Winter Equipment', 'Are heavy-duty roof racks equipped on Nuwara Eliya bound SUVs?', 'responded', 'Vehicles tagged for mountain destinations are properly fitted with racks and all-weather gear.', '2024-02-21 14:10:00'),
                                                                                                         (22, 'Rohan De Silva', 'rohan.desilva@example.com', 'Lost and Found', 'I left my designer sunglasses inside vehicle ID 4. Has the host located them?', 'responded', 'We contacted host Nirosha Perera; she safely secured your sunglasses for pickup.', '2024-02-22 10:05:00'),
                                                                                                         (23, 'Keshani Jayasinghe', 'keshani.j@example.com', 'Multi-Driver Rental', 'Can my spouse drive the vehicle during our reservation period as well?', 'pending', NULL, NULL),
                                                                                                         (24, 'Chula Ranatunga', 'chula.r@example.com', 'Commercial Invoicing', 'Can we obtain tax receipts displaying our registered corporate tax number?', 'responded', 'Submit your registration certificate to support@elitedrive.com for tax invoice generation.', '2024-02-24 15:35:00'),
                                                                                                         (25, 'Vajira Chitrasena', 'vajira.c@example.com', 'Off-Road Policy', 'Is driving the Jeep Wrangler on marked gravel tea estate roads permitted?', 'responded', 'Marked public gravel estate access roads are permitted; extreme unpaved trails require clearance.', '2024-02-25 11:25:00'),
                                                                                                         (26, 'Sajith Premadasa', 'sajith.p@example.com', 'Driver Rating Appeal', 'A guest left an inaccurate driver rating based on unexpected city traffic delays.', 'pending', NULL, NULL),
                                                                                                         (27, 'Jayani Senanayake', 'jayani.s@example.com', 'Delivery Range', 'Can vehicles be delivered fifty kilometers outside central Colombo?', 'pending', NULL, NULL),
                                                                                                         (28, 'Wasantha Kumarasiri', 'wasantha.k@example.com', 'Smoking Violations', 'The vehicle I received smelled like cigarette smoke upon pickup today.', 'responded', 'We have credited your account and dispatched an urgent replacement vehicle immediately.', '2024-02-28 09:15:00'),
                                                                                                         (29, 'Subhashini Pathirage', 'subhashini.p@example.com', 'VIP Concierge', 'Do you provide security escort vehicles along with full size Cadillac Escalades?', 'responded', 'Our premium security fleet concierge can coordinate trained executive protection drivers.', '2024-02-29 13:40:00'),
                                                                                                         (30, 'Aruna Shantha', 'aruna.s@example.com', 'Roadside Assistance', 'What is the direct telephone hotline for 24 hour towing assistance?', 'responded', 'Call 011-555-ELITE for immediate 24/7 complimentary nationwide roadside response.', '2024-03-01 10:00:00'),
                                                                                                         (31, 'Harshani Alahakoon', 'harshani.a@example.com', 'Promotional Codes', 'Where do I apply my new member discount promo voucher during checkout?', 'pending', NULL, NULL),
                                                                                                         (32, 'Gayantha Karunathilaka', 'gayantha.k@example.com', 'Long-Term Booking', 'Do you provide discounted monthly packages for extended movie set production shoots?', 'responded', 'Yes, our production team provides custom multi month fleet rates upon request.', '2024-03-03 16:30:00'),
                                                                                                         (33, 'Kalyani Ranasinghe', 'kalyani.r@example.com', 'Tire Punctures', 'Does comprehensive insurance cover roadside flat tire replacements?', 'responded', 'Flat tire replacement and towing are covered under our roadside assistance bundle.', '2024-03-04 11:45:00'),
                                                                                                         (34, 'Indika Guruge', 'indika.g@example.com', 'Electric Adapter', 'Does the Tesla Model S come with CCS fast charging adapter cables?', 'pending', NULL, NULL),
                                                                                                         (35, 'Chandrika Kumaratunga', 'chandrika.k@example.com', 'Host Payout Schedule', 'When are monthly rental earnings transferred to connected host bank accounts?', 'responded', 'Host payouts transfer automatically every Monday morning via Stripe direct deposit.', '2024-03-06 14:00:00'),
                                                                                                         (36, 'Jayantha Dharmadasa', 'jayantha.d@example.com', 'High Value Insurance', 'Can I increase third party liability limits up to ten million rupees?', 'responded', 'High net worth umbrella liability packages are available through our concierge desk.', '2024-03-07 10:30:00'),
                                                                                                         (37, 'Sujani Menaka', 'sujani.m@example.com', 'Wedding Rental', 'Can we arrange decorative wedding ribbons on luxury vehicles?', 'pending', NULL, NULL),
                                                                                                         (38, 'Nalaka Godahewa', 'nalaka.g@example.com', 'Dashcam Policy', 'Are vehicle dashcams active inside the interior passenger cabin spaces?', 'responded', 'Dashcams face outward only; interior recording devices are strictly prohibited on our fleet.', '2024-03-09 15:10:00'),
                                                                                                         (39, 'Shirani Bandaranayake', 'shirani.b@example.com', 'Window Tinting', 'Are vehicle rear passenger windows tinted for privacy on executive sedans?', 'responded', 'All luxury flagship models feature manufacturer privacy tinted rear glass.', '2024-03-10 12:20:00'),
                                                                                                         (40, 'Thimira Ranasinghe', 'thimira.r@example.com', 'Keyless Entry', 'Can I unlock the vehicle using the smartphone mobile app upon arrival?', 'pending', NULL, NULL),
                                                                                                         (41, 'Deepani Silva', 'deepani.s@example.com', 'Pre-Trip Inspection', 'How do I upload time stamped pictures of existing minor rim scratches?', 'responded', 'Upload exterior inspection images directly through the mobile app prior to unlocking.', '2024-03-12 11:30:00'),
                                                                                                         (42, 'Ranjan Ramanayake', 'ranjan.r@example.com', 'Towing Hitch', 'Can I use the Ford Lightning truck hitch to tow my private speed boat?', 'pending', NULL, NULL),
